import pandas as pd

def clean(df: pd.DataFrame) -> pd.DataFrame:
    df = df.copy()
    # strip whitespace from text columns
    obj_cols = df.select_dtypes(include=['object']).columns
    for c in obj_cols:
        df[c] = df[c].astype(str).str.strip()
    # fix species label variants
    species_map = {"Chinstarp": "Chinstrap"}
    if 'species' in df.columns:
        df['species'] = df['species'].replace(species_map)
    # coerce numeric columns
    num_cols = ['bill_length_mm', 'bill_depth_mm', 'flipper_length_mm', 'body_mass_g', 'year']
    for c in num_cols:
        if c in df.columns:
            df[c] = pd.to_numeric(df[c], errors='coerce')
    # fix sign error in flipper length
    if 'flipper_length_mm' in df.columns:
        neg_mask = df['flipper_length_mm'] < 0
        df.loc[neg_mask, 'flipper_length_mm'] = df.loc[neg_mask, 'flipper_length_mm'].abs()
    # remove exact duplicate rows
    df = df.drop_duplicates()
    # enforce unique penguin_id
    if 'penguin_id' in df.columns:
        df = df.drop_duplicates(subset=['penguin_id'], keep='first')
    return df

def answer(df: pd.DataFrame) -> dict:
    # count penguins per island after cleaning
    if 'island' not in df.columns:
        return {}
    counts = df.groupby('island').size()
    return {str(k): int(v) for k, v in counts.items()}
